      const finish=()=>{clearTimeout(cameraTimer);plane.classList.remove('is-camera-moving');};
      const smooth=()=>{finish();if(!reduced()){plane.classList.add('is-camera-moving');cameraTimer=setTimeout(finish,460);}paint();};
      const zoomTo=(value,at=null)=>{measure();const old=scale;scale=Math.max(1,Math.min(4,value));if(at){const r=cameraRect,px=at.clientX-r.left-r.width/2,py=at.clientY-r.top-r.height/2;x=px-(px-x)*scale/old;y=py-(py-y)*scale/old;}bound();smooth();},zoom=d=>zoomTo(Math.round((scale+d)*10)/10),group=make('div','atlas-zoom-group'),minus=button('−',()=>zoom(-.2)),plus=button('+',()=>zoom(.2)),reset=button('Sıfırla',()=>{measure();x=y=0;scale=1;smooth();});minus.title='Atlası uzaklaştır';plus.title='Atlası yakınlaştır';minus.dataset.zoom='out';plus.dataset.zoom='in';reset.dataset.zoom='reset';reset.setAttribute('aria-label','Görünümü Sıfırla');reset.prepend(window.BookWorld.icon('atlas'));output.setAttribute('aria-label','Harita ölçeği');group.append(minus,plus);tools.append(group,output,reset,range);range.addEventListener('input',()=>{finish();scale=Number(range.value);measure();bound();paint();},{signal:abort.signal});wrapper.append(tools);
